// 1. Accedemos a los datos de entrada
const item = items[0];
const inputData = item.json.data; // Esperamos un array de objetos con la estructura anidada

// 2. Generamos un ID base (timestamp)
const baseId = Date.now();

// 3. Inicializamos el array donde guardaremos el resultado plano
let flatCopies = [];
let counter = 1; // Contador global para los IDs (1, 2, 3, 4, 5, 6...)

// 4. Iteramos sobre cada objeto de framework (AIDA, PAS)
inputData.forEach((dataObject) => {

  // dataObject es ej: { "AIDA": { "small": "...", "mid": "..." } }
  const format = Object.keys(dataObject)[0]; // "AIDA" o "PAS"
  const variations = dataObject[format]; // El objeto con los tamaños

  // 5. Iteramos sobre las claves de tamaño (small, mid, large)
  // Usamos Object.keys para asegurar que recorremos lo que venga
  Object.keys(variations).forEach((size) => {

    // Construimos el objeto plano
    const copyItem = {
      id: `copy_${baseId}_${counter}`,
      format: format,
      size: size,
      text: variations[size],
      isSelected: false,
      isEditable: true
    };

    flatCopies.push(copyItem);
    counter++; // Incrementamos el contador para el siguiente ID
  });
});

// 6. Construimos el objeto de salida final
const output = {
  success: true,
  copies: flatCopies
};

// 7. Retorno para n8n
return [
  {
    json: output
  }
];

